/**
 * Check if a string is a valid date in YYYY-MM-DD format.
 * All dates are interpreted as UTC midnight.
 * @param {string} text
 * @returns {boolean}
 */
export function isValidDate(text) {
  const regex = /^\d{4}-\d{2}-\d{2}$/;
  if (!regex.test(String(text))) return false;

  // Parse as UTC by appending T00:00:00Z
  const date = new Date(text + 'T00:00:00Z');
  if (Number.isNaN(date.getTime())) return false;

  // Verify the date components match (catches invalid dates like 2024-02-30)
  const [year, month, day] = text.split('-').map(Number);
  return (
    date.getUTCFullYear() === year &&
    date.getUTCMonth() + 1 === month &&
    date.getUTCDate() === day
  );
}

/**
 * Add days to a date string, returning the new date in YYYY-MM-DD format.
 * All arithmetic is done in UTC.
 * @param {string} date - Date in YYYY-MM-DD format
 * @param {number} n - Number of days to add (can be negative)
 * @returns {string} - New date in YYYY-MM-DD format
 */
export function addDays(date, n) {
  const d = new Date(date + 'T00:00:00Z');
  d.setUTCDate(d.getUTCDate() + n);
  return d.toISOString().split('T')[0];
}

/**
 * Calculate the difference in days between two dates (b - a).
 * Returns the number of whole days; fractional days are discarded.
 * All arithmetic is done in UTC.
 * @param {string} a - First date in YYYY-MM-DD format
 * @param {string} b - Second date in YYYY-MM-DD format
 * @returns {number} - Difference in whole days (b - a)
 */
export function daysBetween(a, b) {
  const dateA = new Date(a + 'T00:00:00Z');
  const dateB = new Date(b + 'T00:00:00Z');
  const diffMs = dateB.getTime() - dateA.getTime();
  return Math.floor(diffMs / (1000 * 60 * 60 * 24));
}

